    const f = (i + 0.5 + r() * 0.5) / n, ex = x + (r() - 0.5) * h * (0.7 + mains.length * 0.12), ey = b - h * (1.08 + f * (big ? 0.5 : 0.17)) - r() * h * 0.05, sz = h * (0.026 + r() * 0.026) * (1 - f * 0.4)
