    text(ctx, track(`LEVEL ${s.level}`), Font.mediumSystemFont(6.6 * u), 6.6 * u, SILVER, 0.6, cx, cm + 18 * u, "center")
    const line = `TRAIN ${s.exercise}   ·   COOK ${s.cooking}   ·   ${s.badges} BADGES`
